package be.winnetrie.mod.simpleserverutilities.mine;
import java.util.Set;import be.winnetrie.mod.simpleserverutilities.core.module.SsuModule;import be.winnetrie.mod.simpleserverutilities.core.service.SsuServiceRegistry;import net.minecraft.server.MinecraftServer;
public final class MineModule implements SsuModule{private final MineManager manager;private final MineSetupToolManager tools;public MineModule(MineManager manager,MineSetupToolManager tools){this.manager=manager;this.tools=tools;}@Override public String id(){return "mines";}@Override public Set<String> dependencies(){return Set.of("storage","regions","permissions","jobs");}@Override public void initialize(SsuServiceRegistry services){services.register(MineManager.class,manager);services.register(MineSetupToolManager.class,tools);}@Override public void onServerStarting(MinecraftServer server){manager.load(server);}@Override public void onServerStopping(MinecraftServer server){manager.save();manager.clearRuntime();tools.clear();}}
